#include <windows.h>

int main() {
    HANDLE event = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (event == nullptr) {
        return static_cast<int>(GetLastError());
    }

    SetEvent(event);
    DWORD result = WaitForSingleObject(event, 1000);
    if (result != WAIT_OBJECT_0) {
        CloseHandle(event);
        return 1;
    }

    // The manual-reset event remains signaled until reset or closed.
    CloseHandle(event);
    return 0;
}

#include <windows.h>

int main() {
    HANDLE mutex = CreateMutexW(nullptr, FALSE, L"NtExplorerExampleMutex");
    if (mutex == nullptr) {
        return static_cast<int>(GetLastError());
    }

    DWORD result = WaitForSingleObject(mutex, 5000);
    if (result == WAIT_OBJECT_0 || result == WAIT_ABANDONED) {
        // Perform the work guarded by the mutex.
        ReleaseMutex(mutex);
    }

    CloseHandle(mutex);
    return 0;
}

