#include <windows.h>
#include <stdio.h>

static HANDLE g_event = nullptr;

static VOID CALLBACK OnTimer(PVOID, BOOLEAN) {
    SetEvent(g_event);
}

int main() {
    g_event = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (g_event == nullptr) {
        return 1;
    }

    HANDLE queue = CreateTimerQueue();
    HANDLE timer = nullptr;
    if (queue != nullptr &&
        CreateTimerQueueTimer(&timer, queue, OnTimer, nullptr, 10, 0,
            WT_EXECUTEONLYONCE)) {
        WaitForSingleObject(g_event, 1000);
    }

    if (queue != nullptr) {
        DeleteTimerQueueEx(queue, INVALID_HANDLE_VALUE);
    }
    CloseHandle(g_event);
    return 0;
}

