#include <windows.h>
#include <stdio.h>

int main() {
    HANDLE timer = CreateWaitableTimerW(nullptr, TRUE, nullptr);
    if (timer == nullptr) {
        return 1;
    }

    LARGE_INTEGER due = {};
    due.QuadPart = -1000000; // 100 milliseconds in 100-ns units.
    if (SetWaitableTimer(timer, &due, 0, nullptr, nullptr, FALSE)) {
        WaitForSingleObject(timer, 1000);
    }

    CloseHandle(timer);
    return 0;
}

