#include <windows.h>
#include <mmsystem.h>
#include <stdio.h>

#pragma comment(lib, "winmm.lib")

static HANDLE g_event = nullptr;

static void CALLBACK OnTimer(UINT, UINT, DWORD_PTR, DWORD_PTR, DWORD_PTR) {
    SetEvent(g_event);
}

int main() {
    g_event = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (g_event == nullptr) {
        return 1;
    }

    MMRESULT timer = timeSetEvent(10, 1, OnTimer, 0, TIME_ONESHOT);
    if (timer != 0) {
        WaitForSingleObject(g_event, 1000);
        timeKillEvent(timer);
    }

    CloseHandle(g_event);
    return 0;
}

